/// Theme styles of highlighted text.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum Style {
    Keyword,
    String,
    Comment,
    Number,
    Type,
    Function,
    Constant,
    Operator,
    Punctuation,
    Property,
    Tag,
    Attribute,
}

impl Style {
    pub const COUNT: usize = 12;
}

/// Style of a query capture name (`keyword.control`, `string.escape`, ...);
/// `None` for captures drawn as plain text (`variable`, `label`, ...).
pub fn style_of(capture: &str) -> Option<Style> {
    match capture {
        "variable.builtin" => Some(Style::Keyword),
        "variable.member" | "variable.other.member" => Some(Style::Property),
        "string.special.url" | "text.uri" | "string.special.key" => Some(Style::Property),
        "string.escape" | "constant.character.escape" => Some(Style::Constant),
        "text.title" => Some(Style::Keyword),
        "text.literal" => Some(Style::String),
        "text.reference" => Some(Style::Function),
        _ => style_of_head(capture),
    }
}

fn style_of_head(capture: &str) -> Option<Style> {
    let mut parts = capture.split('.');
    Some(match parts.next().unwrap_or("") {
        "keyword" | "conditional" | "repeat" | "include" | "exception" | "storageclass"
        | "preproc" | "define" => Style::Keyword,
        "string" | "character" => Style::String,
        "comment" => Style::Comment,
        "number" | "float" => Style::Number,
        "type" | "constructor" | "module" | "namespace" => Style::Type,
        "function" | "method" => Style::Function,
        "constant" if parts.next() == Some("numeric") => Style::Number,
        "constant" | "boolean" | "escape" => Style::Constant,
        "operator" => Style::Operator,
        "punctuation" | "delimiter" => Style::Punctuation,
        "property" | "field" => Style::Property,
        "tag" => Style::Tag,
        "attribute" => Style::Attribute,
        _ => return None,
    })
}

